// Visit-based planting model: no wall clock, decay, scores or finite seed costs.
export const gardenStages=['Seed','Sprout','Young plant','Grown plant'];
export const gardenSources={starter:'Farm starter packet',tray:'Farm sample tray',forest:'Forest',hills:'Home hills','earth-site':'Earth research site','moon-pod':'Sealed Moon research pod'};
export const gardenBeds=[290,510,730].map((x,i)=>({id:'farm-bed-'+i,zone:'farm',x,y:450,icon:'🌱',name:'Bed '+(i+1),kind:'farm',page:'bed:'+i,gardenBed:i,fact:'Water a planted seed, explore, then return to see one growth stage.'}));
export function emptyGarden(){return {plots:Array.from({length:3},()=>({seed:null,stage:0,watered:false,harvested:false})),grown:[],harvested:[],sources:{}};}
export function normalizeGarden(raw={},seeds=[]){const r=raw&&typeof raw==='object'?raw:{},g=emptyGarden(),known=new Set(seeds);for(let i=0;i<3;i++){const p=r.plots?.[i];if(!p||!known.has(p.seed))continue;const stage=Number.isInteger(p.stage)&&p.stage>=0&&p.stage<=3?p.stage:0;g.plots[i]={seed:p.seed,stage,watered:stage<3&&p.watered===true,harvested:stage===3&&p.harvested===true};}for(const k of ['grown','harvested'])g[k]=[...new Set((Array.isArray(r[k])?r[k]:[]).filter(id=>known.has(id)))];for(const seed of known){const origins=(Array.isArray(r.sources?.[seed])?r.sources[seed]:[]).filter(id=>Object.hasOwn(gardenSources,id));if(origins.length)g.sources[seed]=[...new Set(origins)];}return g;}
export function gardenCollect(g,seed,origin='tray'){if(!Object.hasOwn(gardenSources,origin))origin='tray';g.sources[seed]??=[];if(!g.sources[seed].includes(origin))g.sources[seed].push(origin);}
export function gardenReturn(g){for(const p of g.plots)if(p.seed&&p.watered&&p.stage<3){p.stage++;p.watered=false;if(p.stage===3&&!g.grown.includes(p.seed))g.grown.push(p.seed);}return g;}
export function gardenCommand(g,seeds,action){const index=action.bed,p=Number.isInteger(index)&&index>=0&&index<3?g.plots[index]:null;let message='';
 if(action.command==='plant'){if(p&&seeds.includes(action.seed)&&(!p.seed||p.stage===3)){Object.assign(p,{seed:action.seed,stage:0,watered:false,harvested:false});message='Seed planted. Tap Water, then explore and return.';}else message='Choose an owned seed and an empty or grown bed.';}
 else if(action.command==='water'){if(!p?.seed)message='Choose a seed first.';else if(p.stage===3)message='This plant is grown. You can collect it or plant again.';else if(p.watered)message='Already watered. Explore and return to the farm.';else{p.watered=true;message='Watered! One new stage will appear when you return to the farm.';}}
 else if(action.command==='harvest'&&p?.seed&&p.stage===3){p.harvested=true;if(!g.harvested.includes(p.seed))g.harvested.push(p.seed);message='Harvest saved. This plant can stay, or you can plant another seed.';}
 return {garden:g,message};}
export function gardenFamily(p){return p.tags.includes('trees')?'tree':p.id==='carrot'?'root':p.id==='lettuce'?'leaf':['wheat','rice'].includes(p.id)?'grain':p.tags.includes('flowers')?'flower':p.tags.includes('fruit')?'fruit':'pod';}
export function gardenKey(plot,plants){const p=plants.find(p=>p.id===plot?.seed);return p?'plot-'+gardenFamily(p)+'-'+plot.stage+'-'+Number(plot.watered):'plot-empty';}
export const gardenArtKeys=['plot-empty',...['tree','root','leaf','grain','flower','fruit','pod'].flatMap(f=>Array.from({length:4},(_,i)=>[0,1].map(w=>'plot-'+f+'-'+i+'-'+w)).flat())];
export function gardenArt(key){const [,family='empty',raw='0',wet='0']=key.split('-'),stage=Number(raw);let art='<rect x="40" y="140" width="240" height="27" rx="8" fill="#9a7858"/>';const label=(x,y,t)=>`<text x="${x}" y="${y}" font-family="sans-serif" font-size="15" font-weight="bold" text-anchor="middle" fill="#17384a">${t}</text>`;
 for(let i=0;i<4;i++)art+=`<circle cx="${45+i*29}" cy="24" r="10" fill="${family!=='empty'&&i<=stage?'#d0dfab':'#fffbed'}" stroke="#17384a" stroke-width="2"/>`+label(45+i*29,29,String(i+1));
 if(family==='empty')art+='<path d="M145 110h30m-15-15v30" stroke="#17384a" stroke-width="6"/>';
 else if(stage===0)art+='<ellipse cx="160" cy="145" rx="13" ry="9" fill="#d4ab6c" stroke="#5f503b" stroke-width="3"/>';
 else {const h=stage===1?35:stage===2?70:100;art+=`<path d="M160 145V${145-h}" stroke="#39734d" stroke-width="${stage===3&&family==='tree'?12:6}"/><path d="M160 147l-17 13m17-13 17 13" stroke="#e5e5c8" stroke-width="3"/>`;for(let i=0;i<(stage===1?1:3);i++)art+=`<ellipse cx="${i%2?177:143}" cy="${143-h+i*22}" rx="${stage===3?25:19}" ry="10" fill="#80b769" stroke="#39734d" stroke-width="2"/>`;
 if(stage===3){if(family==='tree')art+='<circle cx="160" cy="73" r="42" fill="#70a165" stroke="#39734d" stroke-width="3"/>';if(family==='flower')for(const [x,y]of [[160,40],[145,52],[175,52],[150,32],[170,32]])art+=`<circle cx="${x}" cy="${y}" r="12" fill="#eec85b" stroke="#8a693d" stroke-width="2"/>`;if(family==='fruit')for(const [x,y]of [[137,83],[180,111],[168,56]])art+=`<circle cx="${x}" cy="${y}" r="10" fill="#d76a58" stroke="#713e36" stroke-width="2"/>`;if(family==='pod')art+='<ellipse cx="185" cy="90" rx="10" ry="28" fill="#a8cd75" stroke="#39734d" stroke-width="3"/><path d="M185 75v30" stroke="#39734d" stroke-width="4" stroke-dasharray="3 6"/>';if(family==='root')art+='<path d="M147 140h26l-13 27z" fill="#dd8d4b" stroke="#895d37" stroke-width="2"/>';if(family==='leaf')for(const [x,y]of [[142,110],[177,110],[160,100],[160,125]])art+=`<ellipse cx="${x}" cy="${y}" rx="23" ry="24" fill="#91c676" stroke="#39734d" stroke-width="3"/>`;if(family==='grain')for(let i=0;i<4;i++)art+=`<path d="M160 ${47+i*12}l-14-10m14 10 14-10" stroke="#d3b66a" stroke-width="7"/>`;}}
 if(wet==='1')art+='<path d="M270 28q-20 25-20 36a20 20 0 0 0 40 0q0-11-20-36z" fill="#82c7da" stroke="#235569" stroke-width="3"/><path d="M255 105h32m-10-9 10 9-10 9" stroke="#235569" stroke-width="4" fill="none"/>';
 return '<svg xmlns="http://www.w3.org/2000/svg" width="320" height="180" viewBox="0 0 320 180"><rect width="320" height="180" rx="16" fill="#edf5df"/>'+art+'</svg>';}
